"""Snapshot source actors near the ego without inferring legal absence.

This is a capture component. A missing actor in this radius is only a scoped
observation; it cannot establish that no relevant hazard or control existed.
"""
from math import hypot, isfinite


def capture(world, ego, *, radius_m=100.0):
    if type(radius_m) not in (int, float) or not isfinite(radius_m) or radius_m <= 0:
        raise ValueError('Scene inventory needs a finite positive radius')
    origin = ego.get_transform().location
    actors = world.get_actors()
    if actors is None:
        raise ValueError('Native actor inventory unavailable')
    rows = []
    seen = set()
    for actor in actors:
        kind = getattr(actor, 'type_id', None)
        if not isinstance(kind, str) or not (
                kind.startswith('vehicle.') or kind == 'traffic.traffic_light'):
            continue
        ident = getattr(actor, 'id', None)
        if type(ident) is not int or ident in seen:
            raise ValueError('Native actor inventory has missing/duplicate identity')
        seen.add(ident)
        position = actor.get_transform().location
        values = (position.x, position.y, position.z)
        if any(type(value) not in (int, float) or not isfinite(value)
               for value in values):
            raise ValueError('Native actor inventory has invalid position')
        distance = hypot(position.x-origin.x, position.y-origin.y)
        if distance > radius_m:
            continue
        row = {'actor_id': ident, 'type_id': kind,
               'position_xyz_m': list(values), 'ego_distance_xy_m': distance}
        if kind == 'traffic.traffic_light':
            row['state'] = str(actor.get_state())
        rows.append(row)
    rows.sort(key=lambda item: item['actor_id'])
    return {'format': 'c179480-native-scene-inventory-v1',
            'source_kind': 'original_carla_actor_and_map_readback',
            'coverage': {'center': 'ego_actor_location', 'radius_m': radius_m,
                         'actor_classes': ['vehicle.*', 'traffic.traffic_light']},
            'actors': rows,
            'interpretation': 'scoped source snapshot only; no legal or physical absence claim'}

"""Source-visible light phase control for the C179480 Native sweep.

The wrapper changes only the surveyed light, before each synchronous world tick.
The original state and frozen flag are restored even if capture fails.
"""
from contextlib import contextmanager

RED_ONSETS_S = (9.0, 11.0, 13.0)


class PhaseWorld:
    def __init__(self, world, light, carla, red_onset_s):
        if red_onset_s not in RED_ONSETS_S:
            raise ValueError('Unreviewed governing red-onset setting')
        if not all(hasattr(light, name) for name in ('get_state', 'set_state', 'freeze', 'is_frozen')):
            raise ValueError('Surveyed light lacks state/freeze readback')
        self.world = world
        self.light = light
        self.green = carla.TrafficLightState.Green
        self.red = carla.TrafficLightState.Red
        self.red_onset_sample = round(red_onset_s * 20)
        self.sample = 0

    def __getattr__(self, name):
        return getattr(self.world, name)

    def tick(self, *args, **kwargs):
        wanted = self.green if self.sample < self.red_onset_sample else self.red
        self.light.set_state(wanted)
        frame = self.world.tick(*args, **kwargs)
        if self.light.get_state() != wanted:
            raise ValueError('Surveyed light did not retain requested state')
        self.sample += 1
        return frame


@contextmanager
def controlled_phase(world, light, carla, red_onset_s):
    if red_onset_s is None:
        yield world
        return
    proxy = PhaseWorld(world, light, carla, red_onset_s)
    original_state = light.get_state()
    original_frozen = light.is_frozen()
    try:
        light.freeze(True)
        if not light.is_frozen():
            raise ValueError('Surveyed light did not freeze for phase control')
        yield proxy
    finally:
        light.set_state(original_state)
        light.freeze(original_frozen)
        if light.get_state() != original_state or light.is_frozen() != original_frozen:
            raise ValueError('Surveyed light state/freeze restoration failed')

"""Exact C179480 sweep case identity and single-axis binding."""

ASSIGNMENT = 'training__C179480__NRS-484B-627-2__motor_vehicle_driver'
BASE = ('reference', 'contrast', 'safe_operation_stop', 'law_required_stop')
SWEEPS = {
    'c179480-traffic-effect-gap': ('reference', 'following_gap_m', (7.0, 12.0, 9.5)),
    'c179480-safe-operation-gap': ('safe_operation_stop', 'hazard_center_gap_m', (6.0, 10.0, 8.0)),
    'c179480-governing-red-onset': ('law_required_stop', 'governing_red_onset_s', (9.0, 13.0, 11.0)),
}


def resolve(config):
    base = config.get('case_suffix')
    if base not in BASE:
        raise ValueError('Unknown C179480 base case')
    sweep = config.get('sweep')
    if sweep is None:
        if config.get('case_id') != ASSIGNMENT+'__'+base:
            raise ValueError('Base case identity differs')
        return base, None, None
    if not isinstance(sweep, dict) or set(sweep) != {'sweep_id', 'sweep_point'}:
        raise ValueError('Incomplete exact sweep binding')
    spec = SWEEPS.get(sweep['sweep_id'])
    if spec is None or spec[0] != base or not isinstance(sweep['sweep_point'], dict):
        raise ValueError('Sweep differs from its Native base case')
    _, axis, values = spec
    if set(sweep['sweep_point']) != {axis}:
        raise ValueError('Sweep must change its one reviewed axis')
    value = sweep['sweep_point'][axis]
    if type(value) not in (int, float) or value not in values:
        raise ValueError('Unreviewed sweep value')
    index = values.index(value)
    if config.get('case_id') not in (
            sweep['sweep_id']+f'-{index:04d}',
            ASSIGNMENT+'__'+sweep['sweep_id']+f'-{index:04d}'):
        raise ValueError('Exact expanded sweep case identity differs')
    return base, axis, value
